#!/usr/bin/env python3
import base64, os
files = {
  '/opt/ogi-logistics/app/quote-manage.tsx': '',
}
for dest, b64 in files.items():
    os.makedirs(os.path.dirname(dest), exist_ok=True)
    with open(dest, "wb") as f:
        f.write(base64.b64decode(b64))
    print(f"Written: {dest}")
print("Done. Run: pm2 restart all")